  "inlineSchema": "// schema.prisma\n\ndatasource db {\n  provider = \"postgresql\" // or postgresql / mysql\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../app/generated/prisma\"\n}\n\n/////////////////////////////////////////////////////\n// 🧑 USER & ROLE MODELS\n/////////////////////////////////////////////////////\n\nmodel User {\n  id            String     @id @default(cuid())\n  name          String\n  email         String     @unique\n  password      String\n  role          Role       @default(USER)\n  image_url     String?\n  addresses     Address[]\n  orders        Order[]\n  reviews       Review[]\n  wishlistItems Wishlist[]\n  cart          Cart?\n  Invoice       Invoice[]\n  createdAt     DateTime   @default(now())\n  updatedAt     DateTime   @updatedAt\n\n  @@map(\"users\")\n}\n\nenum Role {\n  USER\n  ADMIN\n}\n\n/////////////////////////////////////////////////////\n// 🏠 ADDRESS\n/////////////////////////////////////////////////////\n\nmodel Address {\n  id         String   @id @default(cuid())\n  user       User     @relation(fields: [userId], references: [id])\n  userId     String\n  fullName   String\n  phone      String\n  street     String\n  city       String\n  state      String\n  postalCode String\n  country    String\n  isDefault  Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  orders     Order[]\n\n  @@map(\"addresses\")\n}\n\n/////////////////////////////////////////////////////\n// 🏷️ CATEGORY & BRAND\n/////////////////////////////////////////////////////\n\nmodel Category {\n  id          String    @id @default(cuid())\n  name        String\n  slug        String    @unique\n  description String?\n  products    Product[]\n  createdAt   DateTime  @default(now())\n\n  @@map(\"categories\")\n}\n\nmodel Brand {\n  id        String    @id @default(cuid())\n  name      String\n  slug      String    @unique\n  products  Product[]\n  createdAt DateTime  @default(now())\n\n  @@map(\"brands\")\n}\n\n/////////////////////////////////////////////////////\n// 🛍️ PRODUCT & VARIANT\n/////////////////////////////////////////////////////\n\nmodel Product {\n  id            String      @id @default(cuid())\n  name          String\n  slug          String      @unique\n  description   String?\n  price         Float\n  stock         Int         @default(0)\n  images        Json\n  category      Category?   @relation(fields: [categoryId], references: [id])\n  categoryId    String?\n  brand         Brand?      @relation(fields: [brandId], references: [id])\n  brandId       String?\n  productType   ProductType @default(SIMPLE)\n  variants      Variant[]\n  reviews       Review[]\n  wishlistItems Wishlist[]\n  cartItems     CartItem[]\n  orderItems    OrderItem[]\n  createdAt     DateTime    @default(now())\n  updatedAt     DateTime    @updatedAt\n\n  @@map(\"products\")\n}\n\nenum ProductType {\n  SIMPLE\n  VARIABLE\n}\n\nmodel Variant {\n  id         String  @id @default(cuid())\n  product    Product @relation(fields: [productId], references: [id])\n  productId  String\n  name       String\n  sku        String  @unique\n  price      Float\n  stock      Int     @default(0)\n  attributes Json?\n\n  @@map(\"variants\")\n}\n\n/////////////////////////////////////////////////////\n// 💬 REVIEWS\n/////////////////////////////////////////////////////\n\nmodel Review {\n  id        String   @id @default(cuid())\n  rating    Int\n  comment   String?\n  user      User     @relation(fields: [userId], references: [id])\n  userId    String\n  product   Product  @relation(fields: [productId], references: [id])\n  productId String\n  createdAt DateTime @default(now())\n\n  @@map(\"reviews\")\n}\n\n/////////////////////////////////////////////////////\n// ❤️ WISHLIST\n/////////////////////////////////////////////////////\n\nmodel Wishlist {\n  id        String   @id @default(cuid())\n  user      User     @relation(fields: [userId], references: [id])\n  userId    String\n  product   Product  @relation(fields: [productId], references: [id])\n  productId String\n  createdAt DateTime @default(now())\n\n  @@map(\"wishlist\")\n}\n\n/////////////////////////////////////////////////////\n// 🛒 CART\n/////////////////////////////////////////////////////\n\nmodel Cart {\n  id        String     @id @default(cuid())\n  user      User       @relation(fields: [userId], references: [id])\n  userId    String     @unique\n  items     CartItem[]\n  coupon    Coupon?    @relation(fields: [couponId], references: [id])\n  couponId  String?\n  updatedAt DateTime   @updatedAt\n\n  @@map(\"carts\")\n}\n\nmodel CartItem {\n  id                String   @id @default(cuid())\n  cart              Cart     @relation(fields: [cartId], references: [id])\n  cartId            String\n  product           Product  @relation(fields: [productId], references: [id])\n  productId         String\n  variantSelections Json?\n  variantSignature  String?\n  quantity          Int      @default(1)\n  price             Float\n  createdAt         DateTime @default(now())\n\n  @@map(\"cartItems\")\n}\n\n/////////////////////////////////////////////////////\n// 🧾 ORDER\n/////////////////////////////////////////////////////\n\nmodel Order {\n  id             String      @id @default(cuid())\n  user           User        @relation(fields: [userId], references: [id])\n  userId         String\n  address        Address?    @relation(fields: [addressId], references: [id])\n  addressId      String?\n  items          OrderItem[]\n  totalAmount    Float\n  couponCode     String?\n  discountAmount Float       @default(0)\n  status         OrderStatus @default(PENDING)\n  payment        Payment?\n  createdAt      DateTime    @default(now())\n  updatedAt      DateTime    @updatedAt\n\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id        String   @id @default(cuid())\n  order     Order    @relation(fields: [orderId], references: [id])\n  orderId   String\n  product   Product  @relation(fields: [productId], references: [id])\n  productId String\n  quantity  Int\n  price     Float\n  createdAt DateTime @default(now())\n\n  @@map(\"orderItems\")\n}\n\nenum OrderStatus {\n  PENDING\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  CANCELLED\n}\n\n/////////////////////////////////////////////////////\n// 💳 PAYMENT\n/////////////////////////////////////////////////////\n\nmodel Payment {\n  id            String        @id @default(cuid())\n  order         Order         @relation(fields: [orderId], references: [id])\n  orderId       String        @unique\n  method        String\n  transactionId String?\n  status        PaymentStatus @default(PENDING)\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  @@map(\"payments\")\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n}\n\n/////////////////////////////////////////////////////\n// 🎟️ COUPONS\n/////////////////////////////////////////////////////\n\nmodel Coupon {\n  id            String       @id @default(cuid())\n  code          String       @unique\n  description   String?\n  discountType  DiscountType\n  discountValue Float\n  minOrderValue Float?\n  isActive      Boolean      @default(true)\n  expiresAt     DateTime?\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n  carts         Cart[]\n\n  @@map(\"coupons\")\n}\n\nenum DiscountType {\n  PERCENTAGE\n  FIXED\n}\n\nmodel Invoice {\n  id      String        @id @default(cuid())\n  user_id String\n  user    User          @relation(fields: [user_id], references: [id])\n  amount  Int\n  status  InvoiceStatus @default(PENDING)\n  date    DateTime      @default(now())\n\n  @@map(\"invoices\")\n}\n\nenum InvoiceStatus {\n  PENDING\n  PAID\n  FAILED\n}\n\nmodel Revenue {\n  id      String @id @default(cuid())\n  month   String\n  revenue Int\n\n  @@map(\"revenues\")\n}\n",
